/* Silver Arrow — racing silver, sharp edges, opaque. Subtle sheen only; no glass. */
:root {
  color: var(--cu-color-fg-default);
  background: var(--cu-color-background-default);
  font-family: var(--cu-font-family-sans);
  font-synthesis: none;
  letter-spacing: var(--cu-font-tracking-tight);
  line-height: var(--cu-typography-line-height-body);
}

:root .cu-heading,
:root .cu-navbar__brand,
:root .cu-dialog__title {
  font-weight: var(--cu-font-weight-semibold);
  letter-spacing: var(--cu-font-tracking-tight);
}

:root .cu-button {
  letter-spacing: 0.04em;
  font-weight: var(--cu-font-weight-semibold);
}

:root .cu-navbar,
:root .cu-app-shell__header,
:root .cu-tab-bar,
:root .cu-navigation {
  background-color: var(--cu-color-background-subtle);
  background-image: linear-gradient(180deg, var(--cu-color-background-default) 0%, var(--cu-color-background-subtle) 100%);
  border-block-end: 2px solid var(--cu-color-palette-brand);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

:root .cu-tab-bar {
  border-block-end: 0;
  border-block-start: 2px solid var(--cu-color-palette-brand);
}

:root .cu-dialog__content,
:root .cu-app-shell__sidebar {
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  background: var(--cu-color-background-elevated);
}

:root .cu-app-shell__main {
  background: var(--cu-color-background-default);
}

:root .cu-button:focus-visible,
:root .cu-input:focus-visible,
:root .cu-navbar__item:focus-visible,
:root .cu-select__trigger:focus-visible {
  outline-width: 2px;
  outline-offset: 1px;
}

@media (hover: hover) {
  :root .cu-button--solid:hover:not(:disabled) {
    background: color-mix(in srgb, var(--cu-color-palette-brand) 82%, #0f172a);
  }
}

/* Silver Arrow — taut 100ms decelerate. Bezier points stay in [0, 1] (no overshoot). */
:root .cu-button,
:root .cu-navbar__item,
:root .cu-tab-bar__item,
:root .cu-switch__control,
:root .cu-switch__thumb,
:root .cu-alert,
:root .cu-badge,
:root .cu-input,
:root .cu-select__trigger {
  transition-duration: var(--cu-motion-duration-base);
  transition-timing-function: var(--cu-motion-easing-standard);
}

:root .cu-button:hover,
:root .cu-navbar__item:hover,
:root .cu-tab-bar__item:hover {
  transform: none;
}

:root .cu-button:active {
  transform: translateY(1px);
}

@media (prefers-reduced-motion: reduce) {
  :root .cu-button,
  :root .cu-navbar__item,
  :root .cu-tab-bar__item,
  :root .cu-switch__control,
  :root .cu-switch__thumb {
    transition-duration: 0.01ms;
  }

  :root .cu-button:active {
    transform: none;
  }
}

/* Silver Arrow — taut 0/2/4px. Interactive = 0 (sharp), surfaces = lg. No pills. */
:root .cu-button,
:root .cu-badge,
:root .cu-input,
:root .cu-textarea,
:root .cu-select__trigger,
:root .cu-navbar__item,
:root .cu-tag,
:root .cu-search-bar__clear,
:root .cu-search-bar__submit,
:root .cu-checkbox,
:root .cu-switch__control,
:root .cu-switch__thumb {
  border-radius: var(--cu-radius-interactive);
}

:root .cu-card,
:root .cu-alert,
:root .cu-toast,
:root .cu-popover__content,
:root .cu-notification,
:root .cu-code-block,
:root .cu-data-grid,
:root .cu-table {
  border-radius: var(--cu-radius-surface);
}

:root .cu-dialog__content {
  border-radius: var(--cu-radius-md);
  border-start-start-radius: var(--cu-radius-md);
  border-start-end-radius: var(--cu-radius-md);
  border-end-start-radius: var(--cu-radius-md);
  border-end-end-radius: var(--cu-radius-md);
}

:root .cu-button,
:root .cu-badge,
:root .cu-tag {
  border-radius: var(--cu-radius-sm);
}

/* Silver Arrow — border over elevation: taut 1–2px shade, never a soft cloud. */
:root .cu-card--elevated {
  box-shadow: var(--cu-shadow-sm);
  border: 1px solid var(--cu-color-border-default);
}

:root .cu-card--outlined,
:root .cu-toast,
:root .cu-popover__content,
:root .cu-select__content,
:root .cu-dialog__content,
:root .cu-action-sheet {
  box-shadow: var(--cu-shadow-md);
  border: 1px solid var(--cu-color-border-default);
}

:root .cu-button--solid {
  box-shadow: none;
  border: 1px solid color-mix(in srgb, var(--cu-color-palette-brand) 70%, #0f172a);
}

:root .cu-button--outline {
  box-shadow: none;
}

{
  "radius": {
    "$type": "dimension",
    "sm": { "$value": { "value": 0, "unit": "px" } },
    "md": { "$value": { "value": 2, "unit": "px" } },
    "lg": { "$value": { "value": 4, "unit": "px" } },
    "interactive": { "$value": "{radius.sm}" },
    "surface": { "$value": "{radius.lg}" }
  },
  "blur": {
    "$type": "dimension",
    "surface": { "$value": { "value": 0, "unit": "px" } }
  },
  "shadow": {
    "none": { "$value": "none" },
    "sm": { "$value": "0 1px 0 color-mix(in srgb, #0f172a 10%, transparent)" },
    "md": { "$value": "0 1px 2px color-mix(in srgb, #0f172a 12%, transparent)" },
    "lg": { "$value": "0 2px 4px color-mix(in srgb, #0f172a 14%, transparent)" }
  },
  "motion": {
    "duration": {
      "$type": "dimension",
      "fast": { "$value": { "value": 70, "unit": "ms" } },
      "base": { "$value": { "value": 100, "unit": "ms" } }
    },
    "easing": {
      "standard": { "$value": "cubic-bezier(0.2, 0, 0, 1)" }
    }
  },
  "font": {
    "family": {
      "sans": { "$value": "\"Segoe UI\", system-ui, sans-serif" }
    },
    "weight": {
      "semibold": { "$value": 600 },
      "bold": { "$value": 700 }
    },
    "tracking": {
      "tight": { "$value": "-0.03em" }
    }
  },
  "color": {
    "palette": {
      "brand": { "$value": "#5c6b7a" },
      "ink": { "$value": "#1a2330" },
      "paper": { "$value": "#f8fafc" }
    },
    "fg": {
      "muted": { "$value": "#5a6570" }
    },
    "background": {
      "subtle": { "$value": "#e8ecf1" },
      "elevated": { "$value": "#ffffff" }
    },
    "border": {
      "default": { "$value": "#b4bcc6" }
    }
  },
  "typography": {
    "line-height": {
      "body": { "$value": 1.45 }
    }
  }
}
